.component-{{id}}.infinite-scroller {
  display: block;
  position: relative;
  width: 100%;
  max-width: 100%;
  margin: 0;
  overflow: hidden;
  box-sizing: border-box;
  box-shadow: none !important;
  transform: none;
  transition: none;
  vertical-align: top;
}

.component-{{id}} .infinite-scroller__viewport {
  display: block;
  position: relative;
  width: 100%;
  margin: 0;
  overflow: hidden;
  box-shadow: none !important;
}

.component-{{id}} .infinite-scroller__track {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  width: max-content;
  margin: 0;
  white-space: nowrap;
  box-shadow: none !important;
  animation: infinite-scroller-scroll-{{id}} var(--scroller-duration, 30s) linear infinite;
}

.component-{{id}}.pause-in-editor .infinite-scroller__track {
  animation-play-state: paused;
}

.component-{{id}} .infinite-scroller__set {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: nowrap;
  align-items: center;
  min-width: max-content;
  gap: 2.5rem;
  padding-right: 2.5rem;
  white-space: nowrap;
  box-shadow: none !important;
}

.component-{{id}} .infinite-scroller__item,
.component-{{id}} .infinite-scroller__separator {
  display: inline-block;
  flex: 0 0 auto;
  white-space: nowrap;
  box-shadow: none !important;
}

.component-{{id}} .infinite-scroller__accessible {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
  box-shadow: none !important;
}

@keyframes infinite-scroller-scroll-{{id}} {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

@media (prefers-reduced-motion: reduce) {
  .component-{{id}} .infinite-scroller__track {
    animation: none;
    transform: none;
    width: 100%;
    flex-wrap: wrap;
  }

  .component-{{id}} .infinite-scroller__set[aria-hidden="true"] {
    display: none;
  }
}

const transformHook = (rw) => {
  const raw = String(rw.props.items || "").split("\n");
  const values = raw.map((item) => item.trim()).filter(Boolean);
  const weight = ["100", "200", "300", "400", "500", "600", "700", "800", "900"].includes(String(rw.props.fontWeight))
    ? String(rw.props.fontWeight)
    : "700";
  const fontFamilies = {
    body: "'Inter', sans-serif",
    heading: "'Space Grotesk', sans-serif",
    quote: "'Bricolage Grotesque', serif",
    code: "Menlo, Monaco, monospace"
  };
  const fontToken = String(rw.props.fontFamily || "heading");
  const isEdit = rw.project?.mode === "edit";
  const pauseClass = isEdit && rw.props.pauseInEditor !== false ? "pause-in-editor" : "";

  rw.setProps({
    itemList: values.length ? values : ["Add scrolling text in the Inspector"],
    sep: String(rw.props.separator || "•"),
    directionClass: rw.props.direction === "right" ? "direction-right" : "direction-left",
    fontWeightValue: weight,
    fontFamilyCss: fontFamilies[fontToken] || fontFamilies.heading,
    pauseClass
  });
};
exports.transformHook = transformHook;

