.component-{{id}} {
  display: flex !important;
  width: max-content !important;
  max-width: 100%;
  align-items: center;
  justify-content: center;
  min-height: 3rem;
  box-sizing: border-box;
  border-style: solid;
  box-shadow: {{shadowSize}}px {{shadowSize}}px 0 {{shadowColor}};
  font-weight: 800;
  letter-spacing: 0.02em;
  text-decoration: none;
  cursor: pointer;
  transition: transform 140ms ease, box-shadow 140ms ease, background-color 140ms ease, color 140ms ease;
}

.component-{{id}}:hover,
.component-{{id}}:focus-visible {
  transform: translate({{shadowSize}}px, {{shadowSize}}px);
  box-shadow: 0 0 0 {{shadowColor}};
}

.component-{{id}}:active {
  transform: translate({{shadowSize}}px, {{shadowSize}}px) scale(0.98);
}

.component-{{id}}:focus-visible {
  outline: {{focusRingWidth}}px solid {{focusRingColor}};
  outline-offset: 4px;
}

.component-{{id}}.mx-auto {
